  rawText = item.json.choices[0].message.content;
} else if (item.json.response) {
  rawText = item.json.response;
} else if (typeof item.json.text === 'string') {
  rawText = item.json.text;
}

let aiJson = null;
try {
  aiJson = typeof rawText === 'object' ? rawText : JSON.parse(rawText);
} catch (e) {
  return {
    aiSuccess: false,
    statusCode: 500,
    error: "AI Response Parse Error",
    message: "The AI model output could not be parsed as structured JSON."
  };
}

if (!aiJson || !aiJson.basic_information || !aiJson.periods || !Array.isArray(aiJson.periods)) {
  return {
    aiSuccess: false,
    statusCode: 500,
    error: "AI Response Validation Error",
    message: "The AI model returned an incomplete JSON schema missing required lesson plan sections."
  };
}

// Render YAML Frontmatter + 14-Section Markdown Document
const info = aiJson.basic_information || {};
const totalDuration = (info.number_of_periods || norm.numberOfPeriods) * (info.duration_per_period || norm.durationPerPeriod);
const timestampIso = new Date().toISOString();

let md = `---\n`;
md += `title: "Lesson Plan - ${info.topic_chapter || norm.topic}"\n`;
md += `subject: "${info.subject || norm.subject}"\n`;
md += `class_grade: "${info.class_grade || norm.classGrade}"\n`;
md += `topic: "${info.topic_chapter || norm.topic}"\n`;
md += `date: "${info.date || norm.lessonDate}"\n`;
md += `execution_id: "${executionId}"\n`;
md += `generated_at: "${timestampIso}"\n`;
md += `---\n\n`;

md += `# Lesson Plan: ${info.topic_chapter || norm.topic}\n\n`;

// Section 1
md += `## 1. Basic Information\n\n`;
md += `| Field | Details |\n`;
md += `| :--- | :--- |\n`;
md += `| **Teacher** | ${info.teacher || norm.teacherName} |\n`;
md += `| **Institution** | ${info.institution || norm.schoolName} |\n`;
md += `| **Subject** | ${info.subject || norm.subject} |\n`;
md += `| **Class/Grade** | ${info.class_grade || norm.classGrade} |\n`;
md += `| **Board/Curriculum** | ${info.board_curriculum || norm.board} |\n`;
md += `| **Topic/Chapter** | ${info.topic_chapter || norm.topic} |\n`;
md += `| **Date** | ${info.date || norm.lessonDate} |\n`;
md += `| **Number of Periods** | ${info.number_of_periods || norm.numberOfPeriods} |\n`;
md += `| **Duration per Period** | ${info.duration_per_period || norm.durationPerPeriod} minutes (Total: ${totalDuration} mins) |\n\n`;

// Section 2
md += `## 2. Learning Objectives\n\n`;
const objs = Array.isArray(aiJson.objectives) ? aiJson.objectives : [aiJson.objectives || norm.learningObjectives];
objs.forEach(obj => { md += `- ${obj}\n`; });
md += `\n`;

// Section 3
md += `## 3. Learning Outcomes\n\n`;
const outcomes = Array.isArray(aiJson.learning_outcomes) ? aiJson.learning_outcomes : [aiJson.learning_outcomes || 'N/A'];
outcomes.forEach(out => { md += `- ${out}\n`; });
md += `\n`;

// Section 4
md += `## 4. Prerequisite Knowledge\n\n${aiJson.prerequisites || norm.prerequisiteKnowledge}\n\n`;

// Section 5
md += `## 5. Key Concepts and Vocabulary\n\n`;
md += `| Term | Definition | Contextual Usage |\n`;
md += `| :--- | :--- | :--- |\n`;
const terms = Array.isArray(aiJson.key_concepts) ? aiJson.key_concepts : [];
if (terms.length > 0) {
  terms.forEach(t => {
    md += `| **${t.term || ''}** | ${t.definition || ''} | ${t.usage || ''} |\n`;
  });
} else {
  md += `| N/A | N/A | N/A |\n`;
}
md += `\n`;

// Section 6
md += `## 6. Teaching Methodology\n\n${aiJson.methodology || norm.teachingMethod}\n\n`;

// Section 7
md += `## 7. Teaching-Learning Resources\n\n${aiJson.resources || norm.availableResources}\n\n`;

// Section 8
md += `## 8. Period-wise Lesson Plan\n\n`;
const periods = Array.isArray(aiJson.periods) ? aiJson.periods : [];
periods.forEach((p, idx) => {
  md += `### Period ${p.period_number || (idx + 1)} — ${p.title || 'Lesson Period'}\n\n`;
  md += `| Time | Teacher Activity | Student Activity | Assessment |\n`;
  md += `| :--- | :--- | :--- | :--- |\n`;
  const acts = Array.isArray(p.activities) ? p.activities : [];
  acts.forEach(act => {
    md += `| ${act.time || ''} | ${act.teacher_activity || ''} | ${act.student_activity || ''} | ${act.assessment || ''} |\n`;
  });
  md += `\n`;
});

// Section 9
md += `## 9. Differentiation and Learner Support\n\n`;
const diff = aiJson.differentiation || {};
md += `- **Support for Struggling Learners**: ${diff.struggling_learners || 'N/A'}\n`;
md += `- **Extension for Advanced Learners**: ${diff.advanced_learners || 'N/A'}\n`;
md += `- **Accommodations for Special Needs / ELL**: ${diff.special_needs_ell || 'N/A'}\n\n`;

// Section 10
md += `## 10. Assessment Strategy\n\n`;
const assess = aiJson.assessment || {};
md += `- **Formative Assessment**: ${assess.formative || 'N/A'}\n`;
md += `- **Exit Ticket Prompt**: ${assess.exit_ticket || 'N/A'}\n`;
md += `- **Summative Evaluation**: ${assess.summative || 'N/A'}\n\n`;

// Section 11
md += `## 11. Homework / Classwork\n\n${aiJson.homework || norm.homeworkRequirement}\n\n`;

// Section 12
md += `## 12. Remedial and Enrichment Activities\n\n`;
md += `- **Remedial Tasks**: ${aiJson.remedial_activities || 'N/A'}\n`;
md += `- **Enrichment Tasks**: ${aiJson.enrichment_activities || 'N/A'}\n\n`;

// Section 13
md += `## 13. Expected Student Outcomes\n\n${aiJson.expected_outcomes || 'N/A'}\n\n`;

// Section 14
md += `## 14. Teacher Reflection\n\n`;
const refl = aiJson.teacher_reflection || {};
md += `- **What worked well?**: ${refl.what_worked_well || 'N/A'}\n`;
md += `- **What needs improvement?**: ${refl.what_needs_improvement || 'N/A'}\n`;
md += `- **Which students need additional support?**: ${refl.which_students_need_support || 'N/A'}\n`;
md += `- **What should be revisited in the next lesson?**: ${refl.revisit_next_lesson || 'N/A'}\n`;

md += `\n---\n*Generated automatically by Teacher Lesson Plan Automation Pipeline (Execution ID: ${executionId}) on ${timestampIso}*\n`;

// Filename Sanitization & Execution ID Duplicate Protection
const cleanStr = (str) => {
  return (str || '')
    .toString()
    .trim()
    .toLowerCase()
    .replace(/[\\/:*?"<>|]/g, '')
    .replace(/[^a-z0-9_-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
};

const safeSubject = cleanStr(norm.subject) || 'subject';
const safeClass = cleanStr(norm.classGrade) || 'class';
const safeTopic = cleanStr(norm.topic) || 'topic';
const safeDate = cleanStr(norm.lessonDate) || new Date().toISOString().split('T')[0];

const baseStem = `lesson-plan_${safeSubject}_${safeClass}_${safeTopic}_${safeDate}`.slice(0, 80);
const fileName = `${baseStem}_${executionId}.md`;

const outputDir = (process.env.LESSON_PLAN_OUTPUT_DIR || 'c:/Users/manas/OneDrive/Desktop/Teacher Lesson Plan Workflow/lesson_plans').replace(/\\/g, '/');
const filePath = `${outputDir}/${fileName}`;

const binaryBuffer = Buffer.from(md, 'utf8').toString('base64');

return {
  json: {
    aiSuccess: true,
    executionId: executionId,
    fileName,
    filePath,
    outputDir,
    summary: {
      teacherName: norm.teacherName,
      schoolName: norm.schoolName,
      subject: norm.subject,
      classGrade: norm.classGrade,
      topic: norm.topic,
      numberOfPeriods: norm.numberOfPeriods,
      totalDurationMinutes: norm.totalDurationMinutes,
      lessonDate: norm.lessonDate,
      language: norm.language,
      executionId: executionId
    },
    lessonPlanMarkdown: md
  },
  binary: {
    data: {
      data: binaryBuffer,
      mimeType: 'text/markdown',
      fileName: fileName,
      fileExtension: 'md'
    }
  }
};

