try {
  const response = await fetch(REG_API);
  if (!response.ok) {
    return JSON.stringify({ found: false, error: 'Registration API error: ' + response.status });
  }
  const registrations = await response.json();
  const input = typeof query !== 'undefined' ? query : (typeof $input !== 'undefined' && $input.item && $input.item.json ? $input.item.json : {});

  const id = input.id ? String(input.id).trim() : null;
  const email = input.email ? String(input.email).toLowerCase().trim() : null;
  const mobile = input.mobile ? String(input.mobile).replace(/\D/g, '').slice(-10) : null;
  const courseName = input.courseName ? String(input.courseName).toLowerCase().trim() : null;

  let matches = registrations;
  if (id) {
    matches = matches.filter(r => String(r.id).trim() === id);
  } else if (email) {
    matches = matches.filter(r => r.email && r.email.toLowerCase().trim() === email);
  } else if (mobile) {
    matches = matches.filter(r => {
      if (!r.mobile) return false;
      const m = String(r.mobile).replace(/\D/g, '').slice(-10);
      return m === mobile;
    });
  }

  if (courseName && matches.length > 1) {
    matches = matches.filter(r => r.courseName && r.courseName.toLowerCase().includes(courseName));
  }

  if (matches.length === 0) {
    return JSON.stringify({ found: false, message: 'No existing registration found matching the details.' });
  }

  return JSON.stringify({
    found: true,
    count: matches.length,
    registrations: matches
  });
} catch (err) {
  return JSON.stringify({ found: false, error: err.message });
}

