  const scored = allCourses.map(course => {
    let score = 0;
    const reasons = [];
    const cName = (course.courseName || '').toLowerCase();
    const cCat = (course.category || '').toLowerCase();

    for (const kw of targetKeywords) {
      if (kw.includes('web') || kw.includes('dev') || kw.includes('software') || kw.includes('react') || kw.includes('mern') || kw.includes('node') || kw.includes('java')) {
        if (cCat.includes('software') || cName.includes('mern') || cName.includes('react') || cName.includes('node') || cName.includes('java') || cName.includes('python')) {
          score += 30;
          reasons.push('Directly fits software and web development career goals');
        }
      }
      if (kw.includes('data') || kw.includes('analyst') || kw.includes('analytics') || kw.includes('bi') || kw.includes('sql') || kw.includes('excel')) {
        if (cCat.includes('analytics') || cCat.includes('data') || cName.includes('data') || cName.includes('power bi') || cName.includes('sql') || cName.includes('excel')) {
          score += 30;
          reasons.push('Specialized for Data Analytics and BI career path');
        }
      }
      if (kw.includes('ai') || kw.includes('artificial intelligence') || kw.includes('genai') || kw.includes('machine learning')) {
        if (cCat.includes('ai') || cName.includes('ai') || cName.includes('generative') || cName.includes('data science')) {
          score += 30;
          reasons.push('Covers cutting-edge Artificial Intelligence & Data Science curriculum');
        }
      }
      if (kw.includes('design') || kw.includes('ui') || kw.includes('ux') || kw.includes('figma')) {
        if (cCat.includes('design') || cCat.includes('ui') || cName.includes('figma') || cName.includes('graphic')) {
          score += 30;
          reasons.push('Top curriculum for UI/UX & Digital Design');
        }
      }
      if (kw.includes('marketing') || kw.includes('seo') || kw.includes('social media')) {
        if (cCat.includes('marketing') || cName.includes('marketing') || cName.includes('seo')) {
          score += 30;
          reasons.push('Practical Digital Marketing and growth program');
        }
      }
      if (kw.includes('security') || kw.includes('cyber') || kw.includes('cloud') || kw.includes('devops') || kw.includes('aws')) {
        if (cCat.includes('security') || cCat.includes('cloud') || cName.includes('cyber') || cName.includes('cloud') || cName.includes('devops') || cName.includes('aws')) {
          score += 30;
          reasons.push('High-demand infrastructure and cybersecurity curriculum');
        }
      }
      if (cName.includes(kw) || cCat.includes(kw)) {
        score += 20;
        reasons.push('Matches keyword: ' + kw);
      }
    }

    if (maxBudget) {
      const b = Number(maxBudget);
      if (!isNaN(b)) {
        if (course.fees <= b) {
          score += 20;
          reasons.push('Within specified budget of ₹' + b);
        } else {
          score -= 15;
        }
      }
    }

    if (preferredMode && course.mode && course.mode.toLowerCase() === preferredMode.toLowerCase()) {
      score += 15;
      reasons.push('Matches preferred ' + course.mode + ' mode');
    }

    if (preferredTiming) {
      const t = preferredTiming.toLowerCase();
      const bt = (course.batchTime || '').toLowerCase();
      if (t === 'evening' && bt.includes('pm') && (bt.includes('4:') || bt.includes('5:') || bt.includes('6:') || bt.includes('7:') || bt.includes('8:'))) {
